# ThreadLocal引起的内存泄漏
> demo本质是模拟ThreaLocal软引用的key被GC之后，仍能找到这个value存在堆中。
```java
import java.lang.ref.Reference;
import java.lang.reflect.Field;

public class ThreadLocalLeakDemo {

    private static void findLeakedEntries() {
        try {
            Thread t = Thread.currentThread();
            Field threadLocalsField = Thread.class.getDeclaredField("threadLocals");
            threadLocalsField.setAccessible(true);

            Object threadLocalMap = threadLocalsField.get(t);
            if (threadLocalMap == null) {
                System.out.println("ThreadLocalMap 为空");
                return;
            }

            Class<?> mapClass = threadLocalMap.getClass();
            Field tableField = mapClass.getDeclaredField("table");
            tableField.setAccessible(true);

            Object[] table = (Object[]) tableField.get(threadLocalMap);
            System.out.println("开始扫描 ThreadLocalMap Entries...");

            // ✔︎ referent 取自 Reference，而不是 WeakReference
            Field referentField = Reference.class.getDeclaredField("referent");
            referentField.setAccessible(true);

            for (Object entry : table) {
                if (entry == null) continue;

                Class<?> entryClass = entry.getClass();

                Object key = referentField.get(entry);

                Field valueField = entryClass.getDeclaredField("value");
                valueField.setAccessible(true);
                Object value = valueField.get(entry);

                if (key == null && value != null) {
                    System.out.println("⚠️ 发现泄漏：key=null, value=" + value);
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) throws Exception {
        ThreadLocal<String> tl = new ThreadLocal<>();
        tl.set("可能泄漏的值");
        System.out.println("设置 ThreadLocal 值: " + tl.get());

        tl = null;
        System.gc();
        Thread.sleep(1000);

        findLeakedEntries();
    }
}
```

