public static void main(String[] args) {
    // 创建一个模拟 ThreadLocalMap 的 Map，键为 ThreadLocal<?>，值为 Object
    Map<ThreadLocal<?>, Object> threadLocalMap = new HashMap<>();

    // 创建第一个 ThreadLocal 实例
    ThreadLocal<String> tl1 = new ThreadLocal<>();
    tl1.set("Value1");
    // 将 tl1 和它的值放入 map
    threadLocalMap.put(tl1, tl1.get());

    // 创建第二个 ThreadLocal 实例
    ThreadLocal<Integer> tl2 = new ThreadLocal<>();
    tl2.set(123);
    // 将 tl2 和它的值放入 map
    threadLocalMap.put(tl2, tl2.get());

    // 打印这个模拟的 ThreadLocalMap
    System.out.println(threadLocalMap);
}

